contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount) public payable {
        require(address(this).balance >= amount);

        // Record observable state before the deposit.
        uint balanceBefore = address(c).balance;

        c.deposit{value: amount}();

        // Read the caller's credited balance via the public getter generated for `credit`.
        uint creditedBefore = c.credit(address(this));

        // Withdraw all credited Ether.
        c.withdrawAll();

        uint creditedAfter = c.credit(address(this));
        uint balanceAfter = address(c).balance;

        // The general rule: the withdraw removes exactly the previously credited amount,
        // both from the caller's credit and from the contract's Ether balance.
        // Since the test contract is the only depositor, creditedBefore equals the deposited amount.
        assert(creditedAfter == 0 && creditedBefore == amount && balanceBefore + amount == balanceAfter + creditedBefore);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(uint amount1, uint amount2) public payable {
        require(address(this).balance >= amount1 + amount2, "insufficient test contract balance");

        uint totalDeposited = 0;
        uint totalWithdrawn = 0;
        uint balBefore;
        uint balAfter;

        // First deposit by this test contract as caller 1
        c.deposit{value: amount1}();
        totalDeposited += amount1;

        // Read the contract's Ether balance right after the first deposit
        balBefore = address(c).balance;
        // Withdraw the first caller's credit
        c.withdrawAll();
        balAfter = address(c).balance;
        totalWithdrawn += amount1;

        // Second deposit by the same caller but treated as a distinct accounting bucket
        require(address(this).balance >= amount2, "insufficient test contract balance for second deposit");
        c.deposit{value: amount2}();
        totalDeposited += amount2;

        // Withdraw the second caller's credit
        balBefore = address(c).balance;
        c.withdrawAll();
        balAfter = address(c).balance;
        totalWithdrawn += amount2;

        // General rule: address(c).balance == sum(deposits) - sum(actual withdrawals)
        // Since the test contract is the only caller in this run, its credit should be zero at the end.
        // Also, the contract's balance must equal the net deposit amount.
        assert(address(c).balance == totalDeposited - totalWithdrawn);
    }

    receive() external payable {}
}

